const app = document.querySelector('#app');
const toastRoot = document.querySelector('#toast-root');
const state = { user:null, site:null, media:[], pageEditing:null, activeBlock:0, contentType:'article' };

const $ = (s,root=document)=>root.querySelector(s);
const $$ = (s,root=document)=>[...root.querySelectorAll(s)];
const esc = (v='')=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const nl2br = (v='')=>esc(v).replace(/\n/g,'<br>');
const safeHref = (v='#')=>{ try { const s=String(v||'#').trim(); if(s.startsWith('#')||s.startsWith('/')||/^https?:\/\//i.test(s)||/^mailto:/i.test(s)||/^tel:/i.test(s)) return s; } catch{} return '#'; };
const formatDate = v=>v?new Intl.DateTimeFormat('vi-VN',{dateStyle:'medium',timeStyle:'short'}).format(new Date(v)):'—';
const fmtNum = v=>new Intl.NumberFormat('vi-VN').format(Number(v||0));
const roleName = r=>({root_admin:'Root Admin',administrator:'Administrator',content_editor:'Content Editor',project_manager:'Project Manager',volunteer_coordinator:'Volunteer Coordinator',viewer:'Viewer/Auditor'}[r]||r);
const statusName = s=>({draft:'Bản nháp',published:'Đã xuất bản',open:'Đang mở',closed:'Đã đóng',completed:'Hoàn thành',reviewing:'Đang xem xét',archived:'Lưu trữ',new:'Mới',needs_info:'Cần bổ sung',approved:'Đã duyệt',rejected:'Từ chối',pending:'Chờ xác nhận',active:'Đang hoạt động'}[s]||s||'—');
function toast(message,type='ok'){const el=document.createElement('div');el.className=`toast ${type==='error'?'error':''}`;el.textContent=message;toastRoot.append(el);setTimeout(()=>el.remove(),3600)}
async function api(url,options={}){const opts={credentials:'same-origin',...options};if(opts.body&&!(opts.body instanceof FormData)&&typeof opts.body!=='string'){opts.headers={...opts.headers,'Content-Type':'application/json'};opts.body=JSON.stringify(opts.body)}const r=await fetch(url,opts);let data;const ct=r.headers.get('content-type')||'';data=ct.includes('application/json')?await r.json():{message:await r.text()};if(!r.ok)throw new Error(data.error||data.message||`HTTP ${r.status}`);return data}
function icon(name){const map={home:'⌂',web:'▦',page:'▤',news:'✦',media:'▧',project:'◈',activity:'◉',opportunity:'◎',application:'☷',initiative:'◇',impact:'↗',mail:'✉',user:'●',audit:'≡',settings:'⚙',search:'⌕',plus:'＋'};return map[name]||'•'}
function slugify(s=''){return s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/đ/g,'d').replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'').slice(0,120)}

function publicHeader(settings={}){return `<header class="public-header"><div class="container public-nav"><a class="brand" href="/"><img src="${esc(settings.logo_url||'/assets/xanh-sky-first-logo.png')}" alt="Xanh Sky First"><span>XANH SKY FIRST<small>Môi trường & phát triển bền vững</small></span></a><nav class="navlinks"><a href="#gioi-thieu">Giới thiệu</a><a href="#linh-vuc">Hành động</a><a href="#du-an">Dự án</a><a href="#co-hoi">Cơ hội</a><a href="#tin-tuc">Tin tức</a><a href="#tham-gia">Tham gia</a><a href="#lien-he">Kết nối</a></nav><button class="mobile-menu-btn" id="mobile-public-menu" aria-label="Mở menu">☰</button><a class="btn blue" href="#tham-gia">Cùng hành động</a></div><div id="mobile-public-panel" class="hidden" style="padding:15px 20px;border-top:1px solid var(--line);background:#fff"><div class="stack"><a href="#gioi-thieu">Giới thiệu</a><a href="#linh-vuc">Hành động</a><a href="#du-an">Dự án</a><a href="#co-hoi">Cơ hội</a><a href="#tin-tuc">Tin tức</a><a href="#tham-gia">Tham gia</a><a href="#lien-he">Kết nối</a><a href="#login">Đăng nhập quản trị</a></div></div></header>`}
function footer(settings={}){const year=new Date().getFullYear();return `<footer class="site-footer" id="lien-he"><div class="container"><div class="footer-grid"><div class="footer-brand"><img src="${esc(settings.logo_url||'/assets/xanh-sky-first-logo.png')}" alt="Xanh Sky First"><h3>XANH SKY FIRST</h3><p>${esc(settings.footer_intro||'Xanh Sky First là không gian kết nối người trẻ, cộng đồng và hành động vì môi trường, phát triển bền vững.')}</p></div><div><div class="footer-title">KHÁM PHÁ</div><div class="footer-links"><a href="#gioi-thieu">Giới thiệu Xanh</a><a href="#linh-vuc">Lĩnh vực hoạt động</a><a href="#du-an">Dự án</a><a href="#dau-an">Dấu ấn Xanh</a></div></div><div><div class="footer-title">CÙNG HÀNH ĐỘNG</div><div class="footer-links"><a href="#co-hoi">Cơ hội tình nguyện</a><a href="#tham-gia">Tham gia hoạt động</a><a href="#tham-gia">Gửi sáng kiến</a><a href="#lien-he">Hợp tác cùng Xanh</a></div></div><div><div class="footer-title">TÀI NGUYÊN</div><div class="footer-links"><a href="#tin-tuc">Tin tức</a><a href="#tai-nguyen">Thư viện Xanh</a><a href="#tin-tuc">Góc sống xanh</a><a href="#tin-tuc">Kiến thức môi trường</a></div></div><div><div class="footer-title">KẾT NỐI</div><div class="footer-links"><a href="mailto:${esc(settings.email_main||'xanh@skyfirst.io.vn')}">${esc(settings.email_main||'xanh@skyfirst.io.vn')}</a><a href="mailto:${esc(settings.email_partnership||'hoptac@skyfirst.io.vn')}">Hợp tác</a><a href="mailto:${esc(settings.email_media||'truyenthong@skyfirst.io.vn')}">Truyền thông</a><a href="mailto:${esc(settings.email_support||'support@skyfirst.io.vn')}">Hỗ trợ</a><a href="tel:${esc(settings.hotline||'0924910210')}">Hotline/Zalo: 0924 910 210</a><a href="${safeHref(settings.facebook||'https://fb.com/xanhskyfirst')}" target="_blank" rel="noopener">Fanpage ↗</a><a href="${safeHref(settings.community||'https://fb.com/groups/sfn.network')}" target="_blank" rel="noopener">Cộng đồng Sky First ↗</a></div></div></div><div class="footer-bottom"><span>© ${year} Xanh Sky First. Thuộc hệ sinh thái Sky First.</span><span>Quyền riêng tư · Điều khoản · Chính sách dữ liệu · Accessibility · Sitemap · <a href="#login">Quản trị</a></span></div></div></footer>`}

function renderBodyBlocks(blocks=[]){return (blocks||[]).filter(b=>b&&b.visible!==false).map(b=>{switch(b.type){case'heading':return `<h2>${esc(b.text)}</h2>`;case'paragraph':return `<p>${nl2br(b.text)}</p>`;case'quote':return `<blockquote style="border-left:4px solid var(--blue);padding:12px 18px;margin:22px 0;background:#f6f9fb">${nl2br(b.text)}</blockquote>`;case'image':return `<figure><img style="width:${esc(b.width||'100%')};max-height:720px;object-fit:${esc(b.fit||'cover')};object-position:${Number(b.focus_x??.5)*100}% ${Number(b.focus_y??.5)*100}%;border-radius:${Number(b.radius??18)}px" src="${b.media_id?`/api/media/${Number(b.media_id)}`:esc(b.src||'')}" alt="${esc(b.alt||'')}">${b.caption?`<figcaption class="small muted">${esc(b.caption)}</figcaption>`:''}</figure>`;case'cta':return `<p><a class="btn blue" href="${safeHref(b.href)}">${esc(b.label||'Tìm hiểu thêm')}</a></p>`;case'divider':return `<div class="divider"></div>`;case'callout':return `<div class="card" style="padding:20px;background:#f2f8ff"><strong>${esc(b.title||'')}</strong><p>${nl2br(b.text||'')}</p></div>`;default:return''}}).join('')}

function renderSectionBlock(b, dynamic={}){
  if(!b||b.visible===false)return'';
  if(b.type==='hero')return `<section class="hero"><div class="container hero-grid"><div><div class="eyebrow">${esc(b.eyebrow||'XANH SKY FIRST')}</div><h1>${esc(b.title||'Hành động hôm nay. Xanh ngày mai.')}</h1><p>${esc(b.body||'')}</p><div class="hero-actions"><a class="btn blue" href="${safeHref(b.primary_href||'#gioi-thieu')}">${esc(b.primary_label||'Khám phá Xanh')}</a><a class="btn ghost" href="${safeHref(b.secondary_href||'#tham-gia')}">${esc(b.secondary_label||'Cùng hành động')}</a></div></div><div class="hero-visual"><img class="hero-logo" src="${b.media_id?`/api/media/${Number(b.media_id)}`:'/assets/xanh-sky-first-logo.png'}" alt="Xanh Sky First"></div></div></section>`;
  if(b.type==='rich')return `<section class="section" id="gioi-thieu"><div class="container split"><div class="split-media">${b.media_id?`<img src="/api/media/${Number(b.media_id)}" alt="">`:`<img src="/assets/xanh-sky-first-logo.png" alt="Xanh Sky First">`}</div><div><div class="kicker">${esc(b.kicker||'')}</div><h2>${esc(b.title||'')}</h2><p class="lead">${esc(b.body||'')}</p></div></div></section>`;
  if(b.type==='cards')return `<section class="section soft"><div class="container"><div class="kicker">${esc(b.kicker||'')}</div><h2>${esc(b.title||'')}</h2><div class="cards-grid">${(b.items||[]).map((x,i)=>`<article class="card feature-card"><div class="index">0${i+1}</div><h3>${esc(x.title||'')}</h3><p>${esc(x.body||'')}</p></article>`).join('')}</div></div></section>`;
  if(b.type==='feature_grid')return `<section class="section" id="linh-vuc"><div class="container"><div class="kicker">${esc(b.kicker||'')}</div><h2>${esc(b.title||'')}</h2><div class="fields-grid">${(b.items||[]).map((x,i)=>`<div class="card field-tile"><span class="pill green">0${i+1}</span><h3>${esc(typeof x==='string'?x:x.title)}</h3><p class="muted small">Khám phá nội dung, chương trình và tài nguyên liên quan khi dữ liệu được xuất bản.</p></div>`).join('')}</div></div></section>`;
  if(b.type==='dynamic'){const items=dynamic[b.source]||[];const id=b.source==='project'?'du-an':b.source==='opportunity'?'co-hoi':b.source==='article'?'tin-tuc':'content';return `<section class="section ${b.source==='opportunity'?'soft':''}" id="${id}"><div class="container"><div class="kicker">${esc(b.kicker||'')}</div><h2>${esc(b.title||'')}</h2>${items.length?`<div class="content-grid">${items.slice(0,6).map(x=>contentCard(x)).join('')}</div>`:`<div class="empty">Chưa có ${esc(b.source)} được xuất bản. Khi có dữ liệu thật, nội dung sẽ tự động xuất hiện tại đây.</div>`}</div></section>`}
  if(b.type==='impact')return `<section class="section dark impact-wrap" id="dau-an"><div class="container impact-inner"><div class="kicker" style="color:#75d7ff">${esc(b.kicker||'DẤU ẤN XANH')}</div><h2>${esc(b.title||'')}</h2><div id="impact-public" class="impact-grid"><div class="empty" style="grid-column:1/-1;color:#dcecf7;border-color:rgba(255,255,255,.2);background:rgba(255,255,255,.06)">Đang tải dữ liệu tác động đã xác minh…</div></div></div></section>`;
  if(b.type==='newsletter')return `<section class="section" id="newsletter"><div class="container"><div class="newsletter-box"><div><div class="kicker">${esc(b.kicker||'NEWSLETTER')}</div><h2>${esc(b.title||'')}</h2><p class="lead">${esc(b.body||'')}</p></div><form id="newsletter-form" class="stack"><div class="field"><label>Email</label><input class="input" type="email" name="email" required placeholder="ban@example.com"></div><div class="check-row"><label class="check-pill"><input type="checkbox" name="pref" value="activities" checked> Hoạt động mới</label><label class="check-pill"><input type="checkbox" name="pref" value="opportunities"> Cơ hội TNV</label><label class="check-pill"><input type="checkbox" name="pref" value="knowledge"> Kiến thức</label><label class="check-pill"><input type="checkbox" name="pref" value="resources"> Tài nguyên</label></div><button class="btn blue" type="submit">Đăng ký nhận tin</button></form></div></div></section>`;
  if(b.type==='cta')return `<section class="section soft" id="tham-gia"><div class="container"><div class="card" style="padding:52px;background:linear-gradient(135deg,#fff,#edf8f3)"><div class="kicker">${esc(b.kicker||'')}</div><h2>${esc(b.title||'')}</h2><p class="lead">${esc(b.body||'')}</p><div class="row wrap"><button class="btn green" id="open-join">${esc(b.label||'Cùng hành động')}</button><button class="btn ghost" id="open-contact">Kết nối với Xanh</button></div></div></div></section>`;
  return'';
}
function contentCard(x){return `<article class="card content-card"><div class="content-cover">${x.cover_url?`<img loading="lazy" src="${esc(x.cover_url)}" alt="${esc(x.title)}">`:`<img loading="lazy" src="/assets/xanh-sky-first-logo.png" alt="">`}</div><div class="content-body"><span class="pill ${x.status==='completed'?'green':''}">${esc(statusName(x.status))}</span><h3>${esc(x.title)}</h3><p class="muted small">${esc(x.excerpt||'')}</p><div class="small muted">${x.location?`${esc(x.location)} · `:''}${x.published_at?formatDate(x.published_at):''}</div></div></article>`}

async function renderPublic(){app.innerHTML=`<div class="section"><div class="container"><div class="empty">Đang tải Xanh Sky First…</div></div></div>`;try{const site=await api('/api/public/site');state.site=site;const dynamic={};for(const type of ['project','opportunity','article']){try{dynamic[type]=(await api(`/api/public/content?type=${type}`)).items}catch{dynamic[type]=[]}}const settings=site.settings||{},blocks=site.page?.blocks||[];document.title=site.page?.seo?.title||'Xanh Sky First';app.innerHTML=publicHeader(settings)+`<main>${blocks.map(b=>renderSectionBlock(b,dynamic)).join('')}</main>`+footer(settings);wirePublic();loadImpact();}catch(e){app.innerHTML=`${publicHeader({})}<main class="section"><div class="container"><div class="card" style="padding:34px"><div class="kicker">XANH SKY FIRST</div><h1>Website chưa hoàn tất kết nối dữ liệu</h1><p class="lead">${esc(e.message)}</p><p>Hãy áp dụng D1 migration và kiểm tra bindings <b>DB</b> + <b>STORAGE</b>, sau đó tải lại trang.</p><a class="btn blue" href="#login">Mở khu vực quản trị</a></div></div></main>${footer({})}`}}
function wirePublic(){$('#mobile-public-menu')?.addEventListener('click',()=>$('#mobile-public-panel').classList.toggle('hidden'));$('#newsletter-form')?.addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(e.currentTarget);try{await api('/api/public/newsletter',{method:'POST',body:{email:fd.get('email'),preferences:fd.getAll('pref')}});toast('Đã ghi nhận. Vui lòng kiểm tra email xác nhận.');e.currentTarget.reset()}catch(err){toast(err.message,'error')}});$('#open-join')?.addEventListener('click',()=>openJoin());$('#open-contact')?.addEventListener('click',()=>openContact())}
async function loadImpact(){try{const d=await api('/api/public/impact');const items=[['Địa phương đã hoạt động',d.impact.localities],['Lượt TNV tham gia',d.impact.participants],['Hoạt động hoàn thành',d.impact.completed_activities],['Giờ đóng góp cộng đồng',d.impact.volunteer_hours]];const el=$('#impact-public');const valid=items.filter(x=>Number(x[1])>0);el.innerHTML=valid.length?valid.map(([label,v],i)=>`<div class="impact-card"><div class="impact-value" data-count="${Number(v)}">0</div><div class="impact-label">${esc(label)}</div></div>`).join(''):`<div class="empty" style="grid-column:1/-1;color:#dcecf7;border-color:rgba(255,255,255,.2);background:rgba(255,255,255,.06)">Chưa có số liệu tác động đã được xác minh để công bố. Xanh không hiển thị số liệu giả.</div>`;if(valid.length){const obs=new IntersectionObserver(entries=>{for(const en of entries)if(en.isIntersecting){$$('[data-count]',el).forEach(countUp);obs.disconnect()}},{threshold:.25});obs.observe(el)}}catch{}}
function countUp(el){const to=Number(el.dataset.count||0),start=performance.now(),duration=1100;function tick(t){const p=Math.min(1,(t-start)/duration),v=Math.round(to*(1-Math.pow(1-p,3)));el.textContent=fmtNum(v);if(p<1)requestAnimationFrame(tick)}requestAnimationFrame(tick)}
function openJoin(){openModal(`<h2>Tham gia Xanh</h2><p class="muted">Chọn cách bạn muốn bắt đầu. Hồ sơ được lưu vào hệ thống quản lý đơn và có mã theo dõi.</p><form id="join-form" class="stack"><div class="field"><label>Hình thức</label><select class="select" name="kind"><option value="volunteer">Tình nguyện viên</option><option value="activity">Tham gia hoạt động</option><option value="initiative">Gửi sáng kiến</option><option value="expertise">Đóng góp chuyên môn</option><option value="coordinator">Điều phối viên</option></select></div><div class="field"><label>Họ và tên</label><input class="input" name="full_name" required></div><div class="field"><label>Email</label><input class="input" type="email" name="email" required></div><div class="field"><label>Số điện thoại/Zalo</label><input class="input" name="phone"></div><div class="field"><label>Bạn muốn đóng góp điều gì?</label><textarea class="textarea" name="message"></textarea></div><button class="btn green">Gửi đăng ký</button></form>`);$('#join-form').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{const r=await api('/api/public/apply',{method:'POST',body:{kind:f.get('kind'),full_name:f.get('full_name'),email:f.get('email'),phone:f.get('phone'),payload:{message:f.get('message')}}});closeModal();toast(`Đã ghi nhận. Mã hồ sơ: ${r.code}`)}catch(err){toast(err.message,'error')}})}
function openContact(){openModal(`<h2>Kết nối với Xanh</h2><form id="contact-form" class="stack"><div class="field"><label>Nhu cầu</label><select class="select" name="route"><option value="general">Liên hệ Xanh</option><option value="partnership">Hợp tác chương trình</option><option value="media">Truyền thông</option><option value="support">Hỗ trợ kỹ thuật/form</option></select></div><div class="field"><label>Họ tên</label><input class="input" name="full_name" required></div><div class="field"><label>Email</label><input class="input" type="email" name="email" required></div><div class="field"><label>Tiêu đề</label><input class="input" name="subject" required></div><div class="field"><label>Nội dung</label><textarea class="textarea" name="message" required></textarea></div><button class="btn blue">Gửi liên hệ</button></form>`);$('#contact-form').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await api('/api/public/contact',{method:'POST',body:Object.fromEntries(f.entries())});closeModal();toast('Xanh đã ghi nhận liên hệ của bạn.')}catch(err){toast(err.message,'error')}})}

function openModal(html,cls=''){const wrap=document.createElement('div');wrap.className=`modal ${cls}`;wrap.id='global-modal';wrap.innerHTML=`<div class="modal-card"><div class="row between"><div></div><button class="btn ghost sm" data-close>Đóng ✕</button></div>${html}</div>`;document.body.append(wrap);wrap.addEventListener('click',e=>{if(e.target===wrap||e.target.closest('[data-close]'))wrap.remove()})}
function closeModal(){document.querySelector('#global-modal')?.remove()}

async function renderAuth(mode='login'){if(mode==='login'){let initialized=false;try{initialized=(await api('/api/setup')).initialized}catch{}if(!initialized){location.hash='#setup';return}}const resetToken=new URLSearchParams((location.hash.split('?')[1]||'')).get('token');const titles={login:['Đăng nhập','Truy cập Xanh Sky First Management Center'],setup:['Khởi tạo hệ thống','Tạo Root Admin duy nhất cho lần chạy đầu tiên.'],reset:['Đặt lại mật khẩu','Liên kết chỉ sử dụng một lần.']};const [title,desc]=titles[mode]||titles.login;app.innerHTML=`<div class="auth-shell"><section class="auth-brand"><div><img src="/assets/xanh-sky-first-logo.png" alt="Xanh Sky First"><div class="eyebrow" style="color:#7de7d0">XANH SKY FIRST</div><h1>Management<br>Center</h1><p>CMS trực quan, Media Library, dự án, hoạt động, cộng đồng, impact và vận hành hệ thống — trong một giao diện duy nhất.</p><p class="small" style="opacity:.75">PBKDF2-SHA256 được cố định 100.000 iterations cho toàn bộ vòng đời mật khẩu.</p></div></section><section class="auth-form-wrap"><div class="card auth-card"><a href="/" class="small muted">← Về website</a><h2>${title}</h2><p class="muted">${desc}</p>${authForm(mode,resetToken)}</div></section></div>`;wireAuth(mode,resetToken)}
function authForm(mode,token){if(mode==='setup')return `<form id="auth-form"><div class="field"><label>Họ tên</label><input class="input" name="name" required></div><div class="field"><label>Email</label><input class="input" type="email" name="email" required></div><div class="field"><label>Mật khẩu</label><input class="input" type="password" name="password" minlength="10" required></div><div class="field"><label>Xác nhận mật khẩu</label><input class="input" type="password" name="confirm" minlength="10" required></div><div class="field"><label>SETUP_SECRET</label><input class="input" type="password" name="setup_secret" required autocomplete="off"></div><button class="btn blue">Khởi tạo Xanh Sky First</button></form>`;if(mode==='reset')return `<form id="auth-form"><input type="hidden" name="token" value="${esc(token||'')}"><div class="field"><label>Mật khẩu mới</label><input class="input" type="password" name="password" minlength="10" required></div><div class="field"><label>Xác nhận mật khẩu</label><input class="input" type="password" name="confirm" minlength="10" required></div><button class="btn blue">Đặt lại mật khẩu</button></form>`;return `<form id="auth-form"><div class="field"><label>Email</label><input class="input" type="email" name="email" required autocomplete="email"></div><div class="field"><label>Mật khẩu</label><input class="input" type="password" name="password" required autocomplete="current-password"></div><button class="btn blue">Đăng nhập</button><button class="btn ghost" type="button" id="forgot">Quên mật khẩu</button></form>`}
function wireAuth(mode,token){$('#auth-form')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{if(mode==='setup'){if(f.get('password')!==f.get('confirm'))throw new Error('Xác nhận mật khẩu chưa khớp.');await api('/api/setup',{method:'POST',body:{name:f.get('name'),email:f.get('email'),password:f.get('password'),setup_secret:f.get('setup_secret')}})}else if(mode==='reset'){if(f.get('password')!==f.get('confirm'))throw new Error('Xác nhận mật khẩu chưa khớp.');await api('/api/auth/reset-password',{method:'POST',body:{token:f.get('token'),password:f.get('password')}});toast('Đã đổi mật khẩu.');location.hash='#login';return}else await api('/api/auth/login',{method:'POST',body:{email:f.get('email'),password:f.get('password')}});location.hash='#admin/dashboard'}catch(err){toast(err.message,'error')}});$('#forgot')?.addEventListener('click',()=>openModal(`<h2>Quên mật khẩu</h2><p class="muted">Nhập email quản trị. Nếu Resend đã được cấu hình, hệ thống sẽ gửi liên kết đặt lại có hạn 30 phút.</p><form id="forgot-form" class="stack"><input class="input" type="email" name="email" required placeholder="Email quản trị"><button class="btn blue">Gửi hướng dẫn</button></form>`));setTimeout(()=>$('#forgot-form')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{const r=await api('/api/auth/request-reset',{method:'POST',body:{email:f.get('email')}});closeModal();toast(r.message)}catch(err){toast(err.message,'error')}}),0)}

const navGroups=[['TỔNG QUAN',[['dashboard','home','Dashboard']]],['WEBSITE & NỘI DUNG',[['pages','page','Website CMS'],['articles','news','Tin tức'],['resources','web','Tài nguyên'],['media','media','Media Library'],['settings','settings','Menu, Footer & Settings']]],['HOẠT ĐỘNG XANH',[['projects','project','Dự án'],['activities','activity','Hoạt động/Sự kiện'],['opportunities','opportunity','Cơ hội'],['impact','impact','Impact Data']]],['CỘNG ĐỒNG',[['applications','application','Đăng ký & TNV'],['initiatives','initiative','Sáng kiến Xanh']]],['QUẢN TRỊ',[['users','user','Người dùng & quyền'],['audit','audit','Audit Log']]]];
function adminShell(content,route){const user=state.user||{};return `<div class="admin-shell"><aside class="admin-sidebar" id="admin-sidebar"><div class="admin-brand"><img loading="lazy" src="/assets/xanh-sky-first-logo.png" alt=""><span>XANH SKY FIRST<br><small style="font-weight:600;color:#83a5bf">Management Center</small></span></div>${navGroups.map(([label,links])=>`<div class="admin-nav-group"><div class="admin-nav-label">${label}</div><nav class="admin-nav">${links.map(([r,ic,txt])=>`<a href="#admin/${r}" class="${route===r?'active':''}"><span>${icon(ic)}</span>${txt}</a>`).join('')}</nav></div>`).join('')}</aside><main class="admin-main"><header class="admin-topbar"><button class="btn ghost sm hamburger-admin" id="admin-hamb">☰</button><button class="search-trigger" id="command-open">⌕ Tìm kiếm & lệnh nhanh <span style="float:right">Ctrl K</span></button><a class="btn ghost sm" href="/" target="_blank">Xem website ↗</a><div class="admin-user" style="margin-left:12px"><div class="avatar">${esc((user.name||'X')[0])}</div><div class="admin-user-text"><b>${esc(user.name||'')}</b><br><span class="muted small">${esc(roleName(user.role))}</span></div><button class="btn ghost sm" id="logout-btn" title="Đăng xuất">↪</button></div></header><div class="admin-content">${content}</div></main><nav class="mobile-admin-nav"><a href="#admin/dashboard">⌂<span>Home</span></a><a href="#admin/activities">◉<span>Hoạt động</span></a><a href="#admin/applications">☷<span>Đơn</span></a><a href="#admin/media">▧<span>Media</span></a></nav></div>`}
function pageHead(title,desc,actions=''){return `<div class="page-head"><div><h1>${esc(title)}</h1><div class="muted">${esc(desc||'')}</div></div><div class="row wrap">${actions}</div></div>`}
function wireAdminShell(){const hb=$('#admin-hamb'),sb=$('#admin-sidebar');hb?.addEventListener('click',()=>sb.classList.toggle('open'));$('#command-open')?.addEventListener('click',openCommand);$('#logout-btn')?.addEventListener('click',logout);document.addEventListener('keydown',commandShortcut,{once:true})}
function commandShortcut(e){if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openCommand()}document.addEventListener('keydown',commandShortcut,{once:true})}
function openCommand(){openModal(`<div class="field"><input id="command-search" class="input" autofocus placeholder="Tìm lệnh…"></div><div class="command-list" id="command-list">${[['#admin/articles','Tạo / quản lý bài viết'],['#admin/activities','Tạo hoạt động'],['#admin/media','Upload media'],['#admin/applications','Xem đơn mới'],['/','Mở website'],['#admin/settings','Cài đặt']].map(([href,label])=>`<a class="command-item" href="${href}"><span>${label}</span><span>→</span></a>`).join('')}</div>`,'command-modal');setTimeout(()=>$('#command-search')?.focus(),50)}

async function ensureUser(){try{const d=await api('/api/auth/me');state.user=d.user;return !!d.user}catch{return false}}
async function renderAdmin(route){if(!(await ensureUser())){location.hash='#login';return}let content='';try{if(route==='dashboard')content=await adminDashboard();else if(route==='pages')content=await adminPages();else if(route==='media')content=await adminMedia();else if(route==='applications')content=await adminApplications();else if(route==='impact')content=await adminImpact();else if(route==='users')content=await adminUsers();else if(route==='audit')content=await adminAudit();else if(route==='settings')content=await adminSettings();else{const map={articles:'article',projects:'project',activities:'activity',opportunities:'opportunity',resources:'resource',initiatives:'initiative'};content=await adminContentList(map[route]||'article',route)}}catch(e){content=pageHead('Không thể tải dữ liệu',e.message)+`<div class="empty">Kiểm tra migration/binding và quyền tài khoản.</div>`}app.innerHTML=adminShell(content,route);wireAdminShell();wireRoute(route)}

async function adminDashboard(){const d=await api('/api/admin/dashboard');const s=d.stats;return pageHead('Tổng quan',`Xin chào ${state.user.name}. Đây là những gì đang diễn ra tại Xanh Sky First.`,`<a class="btn blue" href="#admin/articles">＋ Tạo nội dung</a><a class="btn green" href="#admin/activities">＋ Tạo hoạt động</a>`)+`<div class="stats-grid"><div class="card stat-card"><div class="muted small">Đơn cần xử lý</div><div class="stat-value">${fmtNum(s.pending_applications)}</div></div><div class="card stat-card"><div class="muted small">Nội dung nháp</div><div class="stat-value">${fmtNum(s.drafts)}</div></div><div class="card stat-card"><div class="muted small">Media Library</div><div class="stat-value">${fmtNum(s.media)}</div></div><div class="card stat-card"><div class="muted small">Lượt tham gia đã xác minh</div><div class="stat-value">${fmtNum(s.participants)}</div></div></div><div class="admin-grid-2"><section class="card panel"><h3>Hoạt động hệ thống gần đây</h3>${d.recent.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Thời gian</th><th>Người dùng</th><th>Hành động</th><th>Đối tượng</th></tr></thead><tbody>${d.recent.map(x=>`<tr><td>${formatDate(x.created_at)}</td><td>${esc(x.user_name||'System')}</td><td>${esc(x.action)}</td><td>${esc(x.object_type)} ${esc(x.object_id||'')}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">Chưa có lịch sử vận hành.</div>`}</section><section class="card panel"><h3>Hệ thống</h3><div class="stack small"><div class="row between"><span>D1 structured data</span><span class="pill green">DB</span></div><div class="row between"><span>R2 Media Storage</span><span class="pill green">STORAGE</span></div><div class="row between"><span>Password KDF</span><b>PBKDF2-SHA256 · 100,000</b></div><div class="row between"><span>Giờ đóng góp xác minh</span><b>${fmtNum(s.volunteer_hours)}</b></div></div></section></div>`}

async function adminPages(){const d=await api('/api/admin/pages');return pageHead('Website CMS','Quản trị trang bằng block editor, tải ảnh và xem trước.','<button class="btn blue" id="new-page">＋ Tạo trang</button>')+`<section class="card panel"><div class="table-wrap"><table class="table"><thead><tr><th>Trang</th><th>Slug</th><th>Trạng thái</th><th>Cập nhật</th><th></th></tr></thead><tbody>${d.items.map(x=>`<tr><td><b>${esc(x.title)}</b></td><td>/${esc(x.slug)}</td><td><span class="pill ${x.status==='published'?'green':'gray'}">${statusName(x.status)}</span></td><td>${formatDate(x.updated_at)}</td><td><button class="btn ghost sm edit-page" data-id="${x.id}">Chỉnh sửa</button></td></tr>`).join('')}</tbody></table></div></section>`}

async function adminContentList(type,route){state.contentType=type;const d=await api(`/api/admin/content?type=${type}`);const label={article:'Tin tức & bài viết',project:'Chương trình & dự án',activity:'Hoạt động & sự kiện',opportunity:'Cổng cơ hội',resource:'Thư viện & tài nguyên',initiative:'Sáng kiến Xanh'}[type];return pageHead(label,'Tạo và quản lý nội dung mà không cần sửa source.',`<button class="btn blue" id="new-content">＋ Tạo ${esc(label)}</button>`)+`<section class="card panel"><div class="toolbar"><input class="input" id="table-search" placeholder="Tìm theo tiêu đề…"><select class="select" id="status-filter"><option value="">Tất cả trạng thái</option><option value="draft">Bản nháp</option><option value="published">Đã xuất bản</option><option value="open">Đang mở</option><option value="completed">Hoàn thành</option></select></div><div class="table-wrap"><table class="table" id="content-table"><thead><tr><th>Tiêu đề</th><th>Trạng thái</th><th>Địa phương</th><th>Cập nhật</th><th></th></tr></thead><tbody>${d.items.map(x=>`<tr data-search="${esc((x.title+' '+(x.location||'')).toLowerCase())}" data-status="${esc(x.status)}"><td><b>${esc(x.title)}</b><div class="small muted">/${esc(x.slug)}</div></td><td><span class="pill ${['published','open','completed'].includes(x.status)?'green':'gray'}">${statusName(x.status)}</span></td><td>${esc(x.location||'—')}</td><td>${formatDate(x.updated_at)}</td><td><button class="btn ghost sm edit-content" data-id="${x.id}">Mở</button></td></tr>`).join('')}</tbody></table></div></section>`}

async function adminMedia(){const d=await api('/api/admin/media');state.media=d.items;return pageHead('Media Library','Tải lên trực tiếp R2. Không cần dán URL ảnh.','<label class="btn blue" for="media-input">＋ Tải lên</label><input class="hidden" id="media-input" type="file" multiple>')+`<div class="upload-zone" id="drop-zone"><b>Kéo thả file vào đây</b><div class="muted small">Ảnh có thể ngang, dọc, vuông hoặc độ phân giải lớn. Hệ thống giữ bản gốc trong R2 và presentation do CMS quyết định.</div></div><div style="height:18px"></div>${mediaGrid(d.items)}`}
function mediaGrid(items=[]){return items.length?`<div class="media-grid" id="media-grid">${items.map(m=>`<div class="card media-card" data-id="${m.id}"><div class="media-thumb">${m.mime_type.startsWith('image/')?`<img src="${esc(m.url)}" alt="${esc(m.alt_text||m.filename)}">`:m.mime_type.startsWith('video/')?`<video src="${esc(m.url)}"></video>`:`<div style="font-size:2rem">▤</div>`}</div><div class="media-meta" title="${esc(m.filename)}">${esc(m.filename)}</div></div>`).join('')}</div>`:`<div class="empty">Media Library đang trống. Tải ảnh/logo/tài liệu đầu tiên để sử dụng trong CMS.</div>`}

async function adminApplications(){const d=await api('/api/admin/applications');return pageHead('Đăng ký & TNV','Mini CRM cho hồ sơ tham gia, cơ hội và tình nguyện viên.')+`<section class="card panel"><div class="toolbar"><select class="select" id="app-filter"><option value="">Tất cả</option><option value="new">Mới</option><option value="reviewing">Đang xem xét</option><option value="needs_info">Cần bổ sung</option><option value="approved">Đã duyệt</option><option value="rejected">Từ chối</option><option value="completed">Hoàn thành</option></select></div><div class="table-wrap"><table class="table"><thead><tr><th>Mã</th><th>Họ tên</th><th>Loại</th><th>Trạng thái</th><th>Thời gian</th><th></th></tr></thead><tbody>${d.items.map(x=>`<tr data-appstatus="${esc(x.status)}"><td><b>${esc(x.code)}</b></td><td>${esc(x.full_name)}<div class="small muted">${esc(x.email)}</div></td><td>${esc(x.kind)}</td><td><span class="pill ${x.status==='approved'||x.status==='completed'?'green':'gray'}">${statusName(x.status)}</span></td><td>${formatDate(x.created_at)}</td><td><button class="btn ghost sm open-app" data-id="${x.id}">Xử lý</button></td></tr>`).join('')}</tbody></table></div></section><script type="application/json" id="applications-data">${JSON.stringify(d.items).replace(/</g,'\\u003c')}</script>`}

async function adminImpact(){const d=await api('/api/admin/impact');const acts=await api('/api/admin/content?type=activity');return pageHead('Impact Data','Chỉ dữ liệu đã xác minh mới được tính vào Dấu ấn Xanh.','<button class="btn green" id="new-impact">＋ Xác nhận dữ liệu</button>')+`<section class="card panel"><div class="table-wrap"><table class="table"><thead><tr><th>Hoạt động</th><th>Địa phương</th><th>TNV</th><th>Giờ</th><th>Hoàn thành</th><th>Xác minh</th></tr></thead><tbody>${d.items.map(x=>`<tr><td>${esc(x.activity_title||`#${x.activity_id}`)}</td><td>${esc(x.locality||'—')}</td><td>${fmtNum(x.confirmed_participants)}</td><td>${fmtNum(x.volunteer_hours)}</td><td>${x.completed?'✓':'—'}</td><td>${x.verified?'<span class="pill green">Đã xác minh</span>':'<span class="pill gray">Chưa xác minh</span>'}</td></tr>`).join('')}</tbody></table></div></section><script type="application/json" id="activities-data">${JSON.stringify(acts.items).replace(/</g,'\\u003c')}</script>`}

async function adminUsers(){const d=await api('/api/admin/users');return pageHead('Người dùng & phân quyền','RBAC được kiểm tra phía backend, không chỉ ẩn menu frontend.','<button class="btn blue" id="new-user">＋ Thêm người dùng</button>')+`<section class="card panel"><div class="table-wrap"><table class="table"><thead><tr><th>Người dùng</th><th>Vai trò</th><th>Trạng thái</th><th>Đăng nhập gần nhất</th></tr></thead><tbody>${d.items.map(x=>`<tr><td><b>${esc(x.name)}</b><div class="small muted">${esc(x.email)}</div></td><td>${esc(roleName(x.role))}</td><td><span class="pill green">${esc(x.status)}</span></td><td>${formatDate(x.last_login_at)}</td></tr>`).join('')}</tbody></table></div></section>`}
async function adminAudit(){const d=await api('/api/admin/audit');return pageHead('Audit Log','Theo dõi các thay đổi quan trọng của hệ thống.')+`<section class="card panel"><div class="table-wrap"><table class="table"><thead><tr><th>Thời gian</th><th>Người dùng</th><th>Hành động</th><th>Đối tượng</th><th>Metadata</th></tr></thead><tbody>${d.items.map(x=>`<tr><td>${formatDate(x.created_at)}</td><td>${esc(x.user_name||'System')}<div class="small muted">${esc(x.user_email||'')}</div></td><td>${esc(x.action)}</td><td>${esc(x.object_type)} ${esc(x.object_id||'')}</td><td class="small">${esc(JSON.stringify(x.metadata||{})).slice(0,160)}</td></tr>`).join('')}</tbody></table></div></section>`}
async function adminSettings(){const d=await api('/api/admin/settings');const s=d.settings||{};return pageHead('Website & System Settings','Thông tin thương hiệu, liên hệ và footer được quản trị tập trung.')+`<form class="card panel stack" id="settings-form"><div class="admin-grid-2" style="margin:0"><div class="stack"><div class="field"><label>Tên website</label><input class="input" name="site_name" value="${esc(s.site_name||'')}"></div><div class="field"><label>Slogan</label><input class="input" name="tagline" value="${esc(s.tagline||'')}"></div><div class="field"><label>Email Xanh</label><input class="input" name="email_main" value="${esc(s.email_main||'')}"></div><div class="field"><label>Email hợp tác</label><input class="input" name="email_partnership" value="${esc(s.email_partnership||'')}"></div><div class="field"><label>Email truyền thông</label><input class="input" name="email_media" value="${esc(s.email_media||'')}"></div><div class="field"><label>Email hỗ trợ</label><input class="input" name="email_support" value="${esc(s.email_support||'')}"></div></div><div class="stack"><div class="field"><label>Hotline/Zalo</label><input class="input" name="hotline" value="${esc(s.hotline||'')}"></div><div class="field"><label>Fanpage</label><input class="input" name="facebook" value="${esc(s.facebook||'')}"></div><div class="field"><label>Cộng đồng Sky First</label><input class="input" name="community" value="${esc(s.community||'')}"></div><div class="field"><label>Giới thiệu Mega Footer</label><textarea class="textarea" name="footer_intro">${esc(s.footer_intro||'')}</textarea></div><div class="field"><label>Logo</label><div class="row"><img id="settings-logo-preview" src="${esc(s.logo_url||'/assets/xanh-sky-first-logo.png')}" style="width:72px;height:72px;object-fit:contain;border:1px solid var(--line);border-radius:14px"><input type="hidden" name="logo_url" value="${esc(s.logo_url||'/assets/xanh-sky-first-logo.png')}"><button type="button" class="btn ghost" id="pick-settings-logo">Chọn từ Media</button></div></div></div></div><button class="btn blue">Lưu cài đặt</button></form>`}

function wireRoute(route){if(route==='pages'){ $$('.edit-page').forEach(b=>b.onclick=()=>openPageEditor(Number(b.dataset.id))); $('#new-page')?.addEventListener('click',newPage)}else if(['articles','projects','activities','opportunities','resources','initiatives'].includes(route)){const type={articles:'article',projects:'project',activities:'activity',opportunities:'opportunity',resources:'resource',initiatives:'initiative'}[route];$('#new-content')?.addEventListener('click',()=>openContentEditor(type));$$('.edit-content').forEach(b=>b.onclick=()=>openContentEditor(type,Number(b.dataset.id)));$('#table-search')?.addEventListener('input',filterContentTable);$('#status-filter')?.addEventListener('change',filterContentTable)}else if(route==='media')wireMedia();else if(route==='applications')wireApplications();else if(route==='impact')wireImpact();else if(route==='users')wireUsers();else if(route==='settings')wireSettings()}
function filterContentTable(){const q=($('#table-search')?.value||'').toLowerCase(),st=$('#status-filter')?.value||'';$$('#content-table tbody tr').forEach(tr=>tr.style.display=(!q||tr.dataset.search.includes(q))&&(!st||tr.dataset.status===st)?'':'none')}

async function newPage(){openModal(`<h2>Tạo trang mới</h2><form id="new-page-form" class="stack"><div class="field"><label>Tiêu đề</label><input class="input" name="title" required></div><div class="field"><label>Slug</label><input class="input" name="slug" placeholder="tự động nếu để trống"></div><button class="btn blue">Tạo trang</button></form>`);$('#new-page-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{const r=await api('/api/admin/pages',{method:'POST',body:{title:f.get('title'),slug:f.get('slug'),blocks:[]}});closeModal();await openPageEditor(r.id)}catch(err){toast(err.message,'error')}}}
async function openPageEditor(id){const d=await api(`/api/admin/page/${id}`);state.pageEditing=d.item;state.activeBlock=0;renderPageEditor()}
function renderPageEditor(){const p=state.pageEditing,b=p.blocks||[];app.innerHTML=adminShell(pageHead(`CMS · ${p.title}`,'Kéo thả section, chỉnh nội dung, chọn ảnh từ Media Library rồi xem trước.',`<button class="btn ghost" id="preview-device">Desktop</button><button class="btn ghost" id="save-draft">Lưu nháp</button><button class="btn blue" id="publish-page">Xuất bản</button>`)+`<div class="cms-layout"><aside class="card cms-sidebar"><div class="row between"><b>Cấu trúc trang</b><button class="btn soft sm" id="add-block">＋</button></div><div style="height:10px"></div><div id="block-list">${b.map((x,i)=>blockRow(x,i)).join('')}</div></aside><section class="card cms-editor"><div class="row between"><h3>Chỉnh section</h3><span class="pill">Visual Editor</span></div><div id="block-fields">${blockFields(b[state.activeBlock],state.activeBlock)}</div><div style="height:20px"></div><div class="row between"><h3>Live Preview</h3><span class="small muted">Không cần chỉnh HTML</span></div><div class="preview-frame"><div class="preview-body" id="page-preview">${previewPageBlocks(b)}</div></div></section></div>`,'pages');wireAdminShell();wirePageEditor()}
function blockRow(b,i){return `<div class="block-row ${i===state.activeBlock?'active':''}" draggable="true" data-i="${i}"><span class="drag">⋮⋮</span><strong>${esc(b.title||b.kicker||b.type||`Block ${i+1}`)}</strong><button class="btn ghost sm block-select" data-i="${i}">Sửa</button><button class="btn danger sm block-delete" data-i="${i}">×</button></div>`}
function blockFields(b,i){if(!b)return`<div class="empty">Chọn hoặc thêm một section.</div>`;return `<div class="block-editor-fields"><div class="two"><div class="field"><label>Loại section</label><input class="input" value="${esc(b.type)}" disabled></div><div class="field"><label>Hiển thị</label><select class="select block-field" data-key="visible"><option value="true" ${b.visible!==false?'selected':''}>Hiện</option><option value="false" ${b.visible===false?'selected':''}>Ẩn</option></select></div></div><div class="field"><label>Kicker / Eyebrow</label><input class="input block-field" data-key="kicker" value="${esc(b.kicker||b.eyebrow||'')}"></div><div class="field"><label>Tiêu đề</label><input class="input block-field" data-key="title" value="${esc(b.title||'')}"></div><div class="field"><label>Nội dung</label><textarea class="textarea block-field" data-key="body">${esc(b.body||'')}</textarea></div><div class="field"><label>Ảnh section</label><div class="row wrap">${b.media_id?`<img src="/api/media/${Number(b.media_id)}" style="width:120px;height:80px;object-fit:cover;border-radius:12px">`:''}<button class="btn ghost" id="pick-block-media">Tải lên / Chọn từ Media</button>${b.media_id?`<button class="btn danger" id="clear-block-media">Bỏ ảnh</button>`:''}</div></div><div class="json-note">Các section chuyên biệt như Cards, Dynamic, Impact vẫn giữ cấu trúc dữ liệu hiện có. Trường phổ biến ở trên được chỉnh trực quan; không yêu cầu Admin sửa code.</div></div>`}
function previewPageBlocks(blocks){return blocks.filter(x=>x.visible!==false).map(x=>{if(x.type==='hero')return`<div style="padding:40px;background:#f0f7ff;border-radius:15px"><div class="kicker">${esc(x.eyebrow||x.kicker||'')}</div><h1>${esc(x.title||'')}</h1><p>${esc(x.body||'')}</p>${x.media_id?`<img src="/api/media/${Number(x.media_id)}" style="max-height:240px;margin:auto">`:''}</div>`;if(x.type==='cards')return`<div style="padding:30px 0"><div class="kicker">${esc(x.kicker||'')}</div><h2>${esc(x.title||'')}</h2><div class="cards-grid">${(x.items||[]).slice(0,4).map(y=>`<div class="card" style="padding:15px"><b>${esc(y.title||'')}</b><p class="small muted">${esc((y.body||'').slice(0,180))}</p></div>`).join('')}</div></div>`;return`<div style="padding:30px 0"><div class="kicker">${esc(x.kicker||'')}</div><h2>${esc(x.title||'')}</h2><p>${esc(x.body||'')}</p>${x.media_id?`<img src="/api/media/${Number(x.media_id)}" style="max-height:260px;object-fit:cover;border-radius:14px">`:''}</div>`}).join('')}
function wirePageEditor(){$$('.block-select').forEach(b=>b.onclick=()=>{state.activeBlock=Number(b.dataset.i);renderPageEditor()});$$('.block-delete').forEach(b=>b.onclick=()=>{state.pageEditing.blocks.splice(Number(b.dataset.i),1);state.activeBlock=Math.max(0,state.activeBlock-1);renderPageEditor()});$$('.block-field').forEach(el=>el.oninput=()=>{const b=state.pageEditing.blocks[state.activeBlock],key=el.dataset.key,val=key==='visible'?el.value==='true':el.value;if(key==='kicker'&&b.eyebrow!==undefined)b.eyebrow=val;else b[key]=val;$('#page-preview').innerHTML=previewPageBlocks(state.pageEditing.blocks)});$('#pick-block-media')?.addEventListener('click',()=>openMediaPicker(id=>{state.pageEditing.blocks[state.activeBlock].media_id=id;renderPageEditor()}));$('#clear-block-media')?.addEventListener('click',()=>{state.pageEditing.blocks[state.activeBlock].media_id=null;renderPageEditor()});$('#add-block').onclick=()=>{state.pageEditing.blocks.push({id:crypto.randomUUID(),type:'rich',kicker:'SECTION',title:'Section mới',body:'Nhập nội dung tại đây.',media_id:null,visible:true});state.activeBlock=state.pageEditing.blocks.length-1;renderPageEditor()};let dragIndex=null;$$('.block-row').forEach(row=>{row.ondragstart=()=>dragIndex=Number(row.dataset.i);row.ondragover=e=>e.preventDefault();row.ondrop=e=>{e.preventDefault();const to=Number(row.dataset.i);if(dragIndex===null||dragIndex===to)return;const [item]=state.pageEditing.blocks.splice(dragIndex,1);state.pageEditing.blocks.splice(to,0,item);state.activeBlock=to;renderPageEditor()}});$('#save-draft').onclick=()=>savePage('draft');$('#publish-page').onclick=()=>savePage('published');$('#preview-device').onclick=e=>{const pv=$('#page-preview');const modes=['','device-tablet','device-mobile'];const names=['Desktop','Tablet','Mobile'];let idx=modes.findIndex(m=>m?pv.classList.contains(m):!pv.classList.contains('device-tablet')&&!pv.classList.contains('device-mobile'));idx=(idx+1)%3;pv.classList.remove('device-tablet','device-mobile');if(modes[idx])pv.classList.add(modes[idx]);e.currentTarget.textContent=names[idx]}}
async function savePage(status){try{await api(`/api/admin/page/${state.pageEditing.id}`,{method:'PUT',body:{title:state.pageEditing.title,status,blocks:state.pageEditing.blocks,seo:state.pageEditing.seo||{}}});state.pageEditing.status=status;toast(status==='published'?'Đã xuất bản trang.':'Đã lưu bản nháp.')}catch(err){toast(err.message,'error')}}

async function openContentEditor(type,id=null){let item={type,title:'',slug:'',excerpt:'',body:[],status:'draft',category:'',location:'',starts_at:'',ends_at:'',capacity:'',cover_media_id:null,metadata:{}};if(id)item=(await api(`/api/admin/content-item/${id}`)).item;openModal(`<h2>${id?'Chỉnh sửa':'Tạo'} ${esc(type)}</h2><form id="content-form" class="stack"><div class="two" style="display:grid;grid-template-columns:1fr 1fr;gap:12px"><div class="field"><label>Tiêu đề</label><input class="input" name="title" value="${esc(item.title)}" required></div><div class="field"><label>Slug</label><input class="input" name="slug" value="${esc(item.slug||'')}"></div></div><div class="field"><label>Tóm tắt</label><textarea class="textarea" name="excerpt">${esc(item.excerpt||'')}</textarea></div><div class="two" style="display:grid;grid-template-columns:1fr 1fr;gap:12px"><div class="field"><label>Trạng thái</label><select class="select" name="status">${['draft','published','open','closed','completed','reviewing'].map(s=>`<option value="${s}" ${item.status===s?'selected':''}>${statusName(s)}</option>`).join('')}</select></div><div class="field"><label>Danh mục</label><input class="input" name="category" value="${esc(item.category||'')}"></div></div><div class="two" style="display:grid;grid-template-columns:1fr 1fr;gap:12px"><div class="field"><label>Địa phương</label><input class="input" name="location" value="${esc(item.location||'')}"></div><div class="field"><label>Số lượng/capacity</label><input class="input" type="number" min="0" name="capacity" value="${esc(item.capacity||'')}"></div></div><div class="two" style="display:grid;grid-template-columns:1fr 1fr;gap:12px"><div class="field"><label>Bắt đầu</label><input class="input" type="datetime-local" name="starts_at" value="${item.starts_at?esc(item.starts_at.slice(0,16)):''}"></div><div class="field"><label>Kết thúc</label><input class="input" type="datetime-local" name="ends_at" value="${item.ends_at?esc(item.ends_at.slice(0,16)):''}"></div></div><div class="field"><label>Ảnh cover</label><div class="row"><div id="cover-preview">${item.cover_media_id?`<img src="/api/media/${item.cover_media_id}" style="width:120px;height:75px;object-fit:cover;border-radius:12px">`:'<span class="muted">Chưa chọn ảnh</span>'}</div><input type="hidden" name="cover_media_id" value="${esc(item.cover_media_id||'')}"><button type="button" class="btn ghost" id="pick-cover">Tải lên / Chọn Media</button></div></div><div class="field"><label>Nội dung bài viết</label><div id="body-blocks" class="stack">${bodyEditorRows(item.body||[])}</div><button class="btn soft" type="button" id="add-body-block">＋ Thêm block</button></div><button class="btn blue">${id?'Lưu thay đổi':'Tạo nội dung'}</button>${id?`<button type="button" class="btn danger" id="delete-content">Xóa nội dung</button>`:''}</form>`);wireContentForm(type,id,item)}
function bodyEditorRows(blocks){return blocks.map((b,i)=>`<div class="card" style="padding:13px" data-body-i="${i}"><div class="row"><select class="select body-type" style="max-width:150px"><option value="paragraph" ${b.type==='paragraph'?'selected':''}>Đoạn văn</option><option value="heading" ${b.type==='heading'?'selected':''}>Tiêu đề</option><option value="quote" ${b.type==='quote'?'selected':''}>Quote</option><option value="callout" ${b.type==='callout'?'selected':''}>Callout</option><option value="image" ${b.type==='image'?'selected':''}>Hình ảnh</option><option value="divider" ${b.type==='divider'?'selected':''}>Divider</option></select><button type="button" class="btn ghost sm body-up">↑</button><button type="button" class="btn ghost sm body-down">↓</button><button type="button" class="btn danger sm body-remove">×</button></div>${bodyBlockFields(b)}</div>`).join('')}
function bodyBlockFields(b){if(b.type==='image')return`<div style="margin-top:10px" class="row wrap"><div>${b.media_id?`<img src="/api/media/${Number(b.media_id)}" style="width:150px;height:95px;object-fit:cover;border-radius:10px">`:'<span class="muted small">Chưa chọn ảnh</span>'}</div><button type="button" class="btn ghost sm body-pick-image">Chọn/Tải ảnh</button><input class="input body-caption" placeholder="Caption" value="${esc(b.caption||'')}" style="flex:1"></div>`;if(b.type==='divider')return'';return`<textarea class="textarea body-text" style="margin-top:10px">${esc(b.text||b.body||'')}</textarea>`}
function wireContentForm(type,id,item){let blocks=item.body||[];const redraw=()=>{$('#body-blocks').innerHTML=bodyEditorRows(blocks);wireBodyRows()};const wireBodyRows=()=>{$$('[data-body-i]').forEach(row=>{const i=Number(row.dataset.bodyI);$('.body-type',row).onchange=e=>{blocks[i]={type:e.target.value,text:''};redraw()};$('.body-text',row)?.addEventListener('input',e=>blocks[i].text=e.target.value);$('.body-caption',row)?.addEventListener('input',e=>blocks[i].caption=e.target.value);$('.body-remove',row).onclick=()=>{blocks.splice(i,1);redraw()};$('.body-up',row).onclick=()=>{if(i>0){[blocks[i-1],blocks[i]]=[blocks[i],blocks[i-1]];redraw()}};$('.body-down',row).onclick=()=>{if(i<blocks.length-1){[blocks[i+1],blocks[i]]=[blocks[i],blocks[i+1]];redraw()}};$('.body-pick-image',row)?.addEventListener('click',()=>openMediaPicker(mid=>{blocks[i].media_id=mid;redraw()}))})};wireBodyRows();$('#add-body-block').onclick=()=>{blocks.push({type:'paragraph',text:''});redraw()};$('#pick-cover').onclick=()=>openMediaPicker(mid=>{$('input[name=cover_media_id]').value=mid;$('#cover-preview').innerHTML=`<img src="/api/media/${mid}" style="width:120px;height:75px;object-fit:cover;border-radius:12px">`});$('#content-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget),body={type,title:f.get('title'),slug:f.get('slug')||slugify(f.get('title')),excerpt:f.get('excerpt'),status:f.get('status'),category:f.get('category'),location:f.get('location'),capacity:f.get('capacity')?Number(f.get('capacity')):null,starts_at:f.get('starts_at')||null,ends_at:f.get('ends_at')||null,cover_media_id:f.get('cover_media_id')?Number(f.get('cover_media_id')):null,body:blocks,metadata:item.metadata||{}};try{if(id)await api(`/api/admin/content-item/${id}`,{method:'PUT',body});else await api('/api/admin/content',{method:'POST',body});closeModal();toast('Đã lưu nội dung.');route()}catch(err){toast(err.message,'error')}};$('#delete-content')?.addEventListener('click',async()=>{if(!confirm('Xóa nội dung này?'))return;try{await api(`/api/admin/content-item/${id}`,{method:'DELETE'});closeModal();toast('Đã xóa nội dung.');route()}catch(err){toast(err.message,'error')}})}

function wireMedia(){const input=$('#media-input'),zone=$('#drop-zone');const uploadFiles=async files=>{for(const file of files){const fd=new FormData();fd.append('file',file);try{await api('/api/admin/media',{method:'POST',body:fd});toast(`Đã tải lên ${file.name}`)}catch(err){toast(`${file.name}: ${err.message}`,'error')}}await route()};input?.addEventListener('change',()=>uploadFiles([...input.files]));zone?.addEventListener('dragover',e=>{e.preventDefault();zone.style.borderColor='var(--blue)'});zone?.addEventListener('dragleave',()=>zone.style.borderColor='');zone?.addEventListener('drop',e=>{e.preventDefault();uploadFiles([...e.dataTransfer.files])});$$('.media-card').forEach(c=>c.onclick=()=>openMediaDetail(Number(c.dataset.id)))}
function openMediaDetail(id){const m=state.media.find(x=>Number(x.id)===id);if(!m)return;openModal(`<h2>Chi tiết Media</h2><div class="admin-grid-2"><div class="media-thumb" style="border-radius:15px;min-height:280px">${m.mime_type.startsWith('image/')?`<img src="${esc(m.url)}" style="object-fit:contain">`:`<div>${esc(m.mime_type)}</div>`}</div><form id="media-meta-form" class="stack"><div><b>${esc(m.filename)}</b><div class="small muted">${fmtNum(m.size_bytes)} bytes · ${esc(m.mime_type)}</div></div><div class="field"><label>Alt text</label><input class="input" name="alt_text" value="${esc(m.alt_text||'')}"></div><div class="field"><label>Caption</label><textarea class="textarea" name="caption">${esc(m.caption||'')}</textarea></div><div class="field"><label>Credit/Nguồn</label><input class="input" name="credit" value="${esc(m.credit||'')}"></div><div class="two" style="display:grid;grid-template-columns:1fr 1fr;gap:12px"><div class="field"><label>Focus X (0–1)</label><input class="input" type="number" min="0" max="1" step=".01" name="focus_x" value="${m.focus_x}"></div><div class="field"><label>Focus Y (0–1)</label><input class="input" type="number" min="0" max="1" step=".01" name="focus_y" value="${m.focus_y}"></div></div><button class="btn blue">Lưu metadata</button><button type="button" class="btn danger" id="delete-media">Xóa file</button></form></div>`);$('#media-meta-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await api(`/api/admin/media-item/${id}`,{method:'PUT',body:{alt_text:f.get('alt_text'),caption:f.get('caption'),credit:f.get('credit'),focus_x:Number(f.get('focus_x')),focus_y:Number(f.get('focus_y'))}});closeModal();toast('Đã cập nhật media.');route()}catch(err){toast(err.message,'error')}};$('#delete-media').onclick=async()=>{if(!confirm('Xóa file khỏi R2 và Media Library?'))return;try{await api(`/api/admin/media-item/${id}`,{method:'DELETE'});closeModal();toast('Đã xóa media.');route()}catch(err){toast(err.message,'error')}}}
async function openMediaPicker(callback){let items=[];try{items=(await api('/api/admin/media')).items}catch{}openModal(`<h2>Chọn từ Media Library</h2><div class="row wrap" style="margin-bottom:15px"><label class="btn blue" for="picker-upload">＋ Tải file mới</label><input id="picker-upload" class="hidden" type="file"></div><div id="picker-grid">${mediaGrid(items.filter(x=>x.mime_type.startsWith('image/')))}</div>`);const wire=()=>$$('#picker-grid .media-card').forEach(c=>c.onclick=()=>{const id=Number(c.dataset.id);closeModal();callback(id)});wire();$('#picker-upload').onchange=async e=>{const file=e.target.files[0];if(!file)return;const fd=new FormData();fd.append('file',file);try{const r=await api('/api/admin/media',{method:'POST',body:fd});closeModal();callback(Number(r.item.id))}catch(err){toast(err.message,'error')}}}

function wireApplications(){let items=[];try{items=JSON.parse($('#applications-data').textContent)}catch{}$('#app-filter')?.addEventListener('change',e=>$$('[data-appstatus]').forEach(tr=>tr.style.display=!e.target.value||tr.dataset.appstatus===e.target.value?'':'none'));$$('.open-app').forEach(b=>b.onclick=()=>{const x=items.find(v=>Number(v.id)===Number(b.dataset.id));if(x)openApplicationDrawer(x)})}
function openApplicationDrawer(x){const backdrop=document.createElement('div'),drawer=document.createElement('aside');backdrop.className='drawer-backdrop';drawer.className='drawer';drawer.innerHTML=`<div class="row between"><div><div class="kicker">${esc(x.code)}</div><h2>${esc(x.full_name)}</h2></div><button class="btn ghost sm" id="drawer-close">✕</button></div><div class="stack"><div class="card panel"><b>Thông tin</b><p>${esc(x.email)}<br>${esc(x.phone||'')}</p><div class="small muted">Loại: ${esc(x.kind)} · ${formatDate(x.created_at)}</div></div><div class="field"><label>Trạng thái</label><select class="select" id="app-status">${['new','reviewing','needs_info','approved','rejected','completed'].map(s=>`<option value="${s}" ${x.status===s?'selected':''}>${statusName(s)}</option>`).join('')}</select></div><div class="field"><label>Ghi chú nội bộ</label><textarea class="textarea" id="app-notes">${esc(x.internal_notes||'')}</textarea></div><button class="btn blue" id="app-save">Lưu xử lý</button></div>`;document.body.append(backdrop,drawer);const close=()=>{backdrop.remove();drawer.remove()};backdrop.onclick=close;$('#drawer-close',drawer).onclick=close;$('#app-save',drawer).onclick=async()=>{try{await api(`/api/admin/application/${x.id}`,{method:'PUT',body:{status:$('#app-status',drawer).value,internal_notes:$('#app-notes',drawer).value}});close();toast('Đã cập nhật hồ sơ.');route()}catch(err){toast(err.message,'error')}}}

function wireImpact(){let acts=[];try{acts=JSON.parse($('#activities-data').textContent)}catch{}$('#new-impact')?.addEventListener('click',()=>{openModal(`<h2>Xác nhận dữ liệu tác động</h2><p class="muted">Chỉ bật “Đã xác minh” sau khi số liệu đã được đối chiếu. Dữ liệu này đi thẳng vào counter công khai.</p><form id="impact-form" class="stack"><div class="field"><label>Hoạt động</label><select class="select" name="activity_id">${acts.map(a=>`<option value="${a.id}">${esc(a.title)}</option>`).join('')}</select></div><div class="field"><label>Địa phương</label><input class="input" name="locality"></div><div class="two" style="display:grid;grid-template-columns:1fr 1fr;gap:12px"><div class="field"><label>TNV xác nhận</label><input class="input" type="number" min="0" name="confirmed_participants" value="0"></div><div class="field"><label>Giờ đóng góp</label><input class="input" type="number" min="0" step=".5" name="volunteer_hours" value="0"></div></div><label class="check-pill"><input type="checkbox" name="completed"> Hoạt động đã hoàn thành</label><label class="check-pill"><input type="checkbox" name="verified"> Dữ liệu đã được xác minh</label><div class="field"><label>Ghi chú đối chiếu</label><textarea class="textarea" name="notes"></textarea></div><button class="btn green">Lưu Impact</button></form>`);$('#impact-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await api('/api/admin/impact',{method:'POST',body:{activity_id:Number(f.get('activity_id')),locality:f.get('locality'),confirmed_participants:Number(f.get('confirmed_participants')),volunteer_hours:Number(f.get('volunteer_hours')),completed:f.has('completed'),verified:f.has('verified'),notes:f.get('notes')}});closeModal();toast('Đã cập nhật impact.');route()}catch(err){toast(err.message,'error')}}})}

function wireUsers(){$('#new-user')?.addEventListener('click',()=>{openModal(`<h2>Thêm người dùng quản trị</h2><form id="user-form" class="stack"><div class="field"><label>Họ tên</label><input class="input" name="name" required></div><div class="field"><label>Email</label><input class="input" type="email" name="email" required></div><div class="field"><label>Vai trò</label><select class="select" name="role"><option value="administrator">Administrator</option><option value="content_editor">Content Editor</option><option value="project_manager">Project Manager</option><option value="volunteer_coordinator">Volunteer Coordinator</option><option value="viewer">Viewer/Auditor</option></select></div><div class="field"><label>Mật khẩu tạm (≥10 ký tự)</label><input class="input" type="password" minlength="10" name="password" required></div><button class="btn blue">Tạo tài khoản</button></form>`);$('#user-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await api('/api/admin/users',{method:'POST',body:Object.fromEntries(f.entries())});closeModal();toast('Đã tạo người dùng với PBKDF2 100.000 iterations.');route()}catch(err){toast(err.message,'error')}}})}
function wireSettings(){$('#settings-form')?.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await api('/api/admin/settings',{method:'PUT',body:Object.fromEntries(f.entries())});toast('Đã lưu cài đặt website.')}catch(err){toast(err.message,'error')}});$('#pick-settings-logo')?.addEventListener('click',()=>openMediaPicker(id=>{$('input[name=logo_url]').value=`/api/media/${id}`;$('#settings-logo-preview').src=`/api/media/${id}`}))}

async function logout(){try{await api('/api/auth/logout',{method:'POST'})}catch{}state.user=null;location.hash='#login'}

async function route(){const hash=location.hash||'';if(hash.startsWith('#setup'))return renderAuth('setup');if(hash.startsWith('#reset-password'))return renderAuth('reset');if(hash.startsWith('#login'))return renderAuth('login');if(hash.startsWith('#admin/'))return renderAdmin(hash.replace('#admin/','').split('?')[0]||'dashboard');return renderPublic()}
window.addEventListener('hashchange',route);route();
